SELECT movement_time,direction,warehouse_code,sku_code,quantity,reference,order_status,source_kind,source_label FROM (
SELECT COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created) movement_time,'out' direction,c.wms_code warehouse_code,b.sku_code,SUM(b.request_qty) quantity,h.transfer_order_code reference,h.order_status,'transfer_request' source_kind,'调拨申请出库' source_label FROM scm_transfer_order_header h JOIN scm_transfer_order_detail b ON h.transfer_order_code=b.transfer_order_code LEFT JOIN master_wms c ON h.delivery_wms=c.wms_code LEFT JOIN master_wms d ON h.receive_wms=d.wms_code WHERE h.status=0 AND b.status=0 AND c.wms_node=14 AND (d.wms_node=15 OR (d.wms_node=14 AND d.wms_code='WMS000097')) AND b.sku_code=[DYNAMIC_PARAMS.sku_code] AND c.wms_code=[DYNAMIC_PARAMS.warehouse_code] AND COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created)>=[DYNAMIC_PARAMS.t1] AND COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created)<DATE_ADD([DYNAMIC_PARAMS.t2],INTERVAL 1 DAY) GROUP BY COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created),h.transfer_order_code,h.order_status,c.wms_code,b.sku_code
UNION ALL
SELECT COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created),'in',c.wms_code,b.sku_code,SUM(b.request_qty),h.transfer_order_code,h.order_status,'transfer_request','调拨申请入库' FROM scm_transfer_order_header h JOIN scm_transfer_order_detail b ON h.transfer_order_code=b.transfer_order_code LEFT JOIN master_wms c ON h.receive_wms=c.wms_code LEFT JOIN master_wms d ON h.delivery_wms=d.wms_code WHERE h.status=0 AND b.status=0 AND c.wms_node=14 AND d.wms_node=15 AND b.sku_code=[DYNAMIC_PARAMS.sku_code] AND c.wms_code=[DYNAMIC_PARAMS.warehouse_code] AND COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created)>=[DYNAMIC_PARAMS.t1] AND COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created)<DATE_ADD([DYNAMIC_PARAMS.t2],INTERVAL 1 DAY) GROUP BY COALESCE(h.plan_store_time,h.scheduled_ship_date,h.created),h.transfer_order_code,h.order_status,c.wms_code,b.sku_code
UNION ALL
SELECT COALESCE(sh.scheduled_ship_on,sh.ship_at,sh.created),'out',a.wms_code,a.sku_code,SUM(COALESCE(a.actual_quantity,a.allocate_qty,0)),a.outbound_code,CAST(sh.status AS CHAR),'sales_shipment','销售出库' FROM scm_sales_shipment_allocate_wms a JOIN scm_sales_shipment_header sh ON sh.outbound_code=a.outbound_code LEFT JOIN master_wms mw ON mw.wms_code=a.wms_code WHERE a.status='0' AND COALESCE(a._fdl_marked_deleted,'0')<>'1' AND sh.delete_flag=0 AND sh.status IN (700,900,701,901) AND mw.wms_type=12 AND mw.wms_status<>12 AND a.sku_code=[DYNAMIC_PARAMS.sku_code] AND a.wms_code=[DYNAMIC_PARAMS.warehouse_code] AND COALESCE(sh.scheduled_ship_on,sh.ship_at,sh.created)>=[DYNAMIC_PARAMS.t1] AND COALESCE(sh.scheduled_ship_on,sh.ship_at,sh.created)<DATE_ADD([DYNAMIC_PARAMS.t2],INTERVAL 1 DAY) AND NOT EXISTS (SELECT 1 FROM scm_transfer_order_header tx WHERE tx.outbound_code=a.outbound_code AND tx.status=0) GROUP BY COALESCE(sh.scheduled_ship_on,sh.ship_at,sh.created),a.outbound_code,sh.status,a.wms_code,a.sku_code
UNION ALL
SELECT COALESCE(h.actual_arrival_date,h.created_date),'in',h.wms_code,d.sku_code,SUM(COALESCE(d.received_quantity,d.total_quantity,0)),h.warehous_code,h.approve_status,'warehouse_receipt','仓库入库' FROM scm_warehous_header h JOIN scm_warehous_detail d ON h.warehous_code=d.warehous_code LEFT JOIN master_wms mw ON mw.wms_code=h.wms_code WHERE h.status='0' AND h.approve_status='12' AND COALESCE(h._fdl_marked_deleted,'0')<>'1' AND COALESCE(d._fdl_marked_deleted,'0')<>'1' AND mw.wms_type=12 AND mw.wms_status<>12 AND d.sku_code=[DYNAMIC_PARAMS.sku_code] AND h.wms_code=[DYNAMIC_PARAMS.warehouse_code] AND COALESCE(h.actual_arrival_date,h.created_date)>=[DYNAMIC_PARAMS.t1] AND COALESCE(h.actual_arrival_date,h.created_date)<DATE_ADD([DYNAMIC_PARAMS.t2],INTERVAL 1 DAY) GROUP BY COALESCE(h.actual_arrival_date,h.created_date),h.warehous_code,h.approve_status,h.wms_code,d.sku_code
UNION ALL
SELECT d.created_date,CASE WHEN d.adjust_quantity>=0 THEN 'in' ELSE 'out' END,d.wms_code,d.sku_code,ABS(d.adjust_quantity),d.adjust_code,h.approve_status,'inventory_adjustment','库存调整' FROM scm_wms_adj_detail d LEFT JOIN scm_wms_adj_header h ON h.adjust_code=d.adjust_code LEFT JOIN master_wms mw ON mw.wms_code=d.wms_code WHERE d.status='0' AND COALESCE(d._fdl_marked_deleted,'0')<>'1' AND (h.status IS NULL OR h.status='0') AND mw.wms_type=12 AND mw.wms_status<>12 AND d.sku_code=[DYNAMIC_PARAMS.sku_code] AND d.wms_code=[DYNAMIC_PARAMS.warehouse_code] AND d.created_date>=[DYNAMIC_PARAMS.t1] AND d.created_date<DATE_ADD([DYNAMIC_PARAMS.t2],INTERVAL 1 DAY)
) movements LIMIT 5001
